import * as THREE from 'three';
import { OBJExporter } from 'three/examples/jsm/exporters/OBJExporter.js';
import { createScene } from './data/object.js';
import fs from 'fs';
import path from 'path';

// Mock DOM elements if necessary (Three.js usually doesn't need them for OBJExporter, but just in case)
// Actually, OBJExporter is pure JS logic on Object3D and Geometry.

async function run() {
    try {
        console.log("Initializing...");

        // 1. Create the scene
        const scene = createScene();
        if (!scene) {
            throw new Error("createScene() returned nothing.");
        }
        console.log("Scene created.");

        // 2. Apply -90 degrees X-rotation for Blender Z-up space
        // We wrap the scene in a container to apply the rotation to the whole hierarchy
        const container = new THREE.Group();
        container.add(scene);

        container.rotation.x = -Math.PI / 2;

        // IMPORTANT: Update the world matrices so the exporter sees the transformed positions
        container.updateMatrixWorld(true);
        console.log("Rotation applied and matrices updated.");

        // 3. Export to OBJ
        const exporter = new OBJExporter();
        console.log("Parsing scene to OBJ...");
        const objData = exporter.parse(container);

        // 4. Write to file
        const outputDir = './output';
        if (!fs.existsSync(outputDir)){
            fs.mkdirSync(outputDir);
        }
        const outputPath = path.join(outputDir, 'object.obj');

        fs.writeFileSync(outputPath, objData);
        console.log(`Successfully exported to ${outputPath}`);

    } catch (error) {
        console.error("An error occurred:", error);
        process.exit(1);
    }
}

run();

